import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s3-u07")
C = "A2"

L(1, "O corpo", "het hoofd, de arm, de hand, het been, de rug, de buik.",
  ["Nomear as partes do corpo"],
  vocab=[V("v-hoofd","hoofd","cabeça","noun","het","hoofden"), V("v-arm","arm","braço","noun","de","armen"), V("v-hand","hand","mão","noun","de","handen"),
         V("v-rug","rug","costas","noun","de",note="Singular: mijn rug doet pijn = doem-me as costas."), V("v-buik","buik","barriga","noun","de"),
         V("v-keel","keel","garganta","noun","de"), V("v-oog","oog","olho","noun","het","ogen")],
  ex=[("Mijn hoofd doet pijn.","Dói-me a cabeça."),("Ik heb pijn in mijn rug.","Tenho dores nas costas."),("Hij heeft blauwe ogen.","Ele tem olhos azuis.")],
  gram=[G("g-pijn","Dores: pijn doen / pijn hebben","Duas formas: **Mijn hoofd doet pijn** (a minha cabeça dói) ou **Ik heb pijn in mijn rug** (tenho dores nas costas). Também há compostos: **hoofdpijn** (dor de cabeça), **buikpijn**, **keelpijn**, **rugpijn**: *ik heb hoofdpijn*.",
    [("Ik heb keelpijn.","Tenho dores de garganta.")],
    "Em português «dói-me a cabeça» usa o pronome «me»; em neerlandês usa-se o possessivo: «mijn hoofd doet pijn».")],
  review=["v-been","v-doen","v-hebben"],
  cefr=C, exs=[
    MA([("hoofd","cabeça"),("arm","braço"),("hand","mão"),("rug","costas"),("buik","barriga")], "Corpo.", ["v-hoofd","v-arm","v-hand","v-rug","v-buik"]),
    AR("hoofd","a cabeça","het", "«Het hoofd».", ["v-hoofd"]),
    AR("oog","o olho","het", "«Het oog» — plural «ogen».", ["v-oog"]),
    TR("pt-nl","Dói-me a cabeça.", ["Mijn hoofd doet pijn","Ik heb hoofdpijn"], "mijn hoofd doet pijn.", ["v-hoofd"]),
    TR("pt-nl","Tenho dores de garganta.", ["Ik heb keelpijn","Mijn keel doet pijn","Ik heb pijn in mijn keel"], "keelpijn.", ["v-keel"]),
    TR("nl-pt","Ik heb pijn in mijn rug.", ["Tenho dores nas costas","Doem-me as costas"], "rug é singular.", ["v-rug"]),
    FE(["Mijn","hoofd","doen","pijn."], 2, "doet", "het hoofd → doet.", ["v-hoofd"]),
    MC("Plural de «oog»:", ["*ogen","oogen|Sílaba aberta: o-gen.","oogs|Não."], "oog → ogen.", ["v-oog"]),
    LI("Ik heb buikpijn.", ["Ik heb buikpijn"], "Tenho dores de barriga.", "buik + pijn.", ["v-buik"]),
    FB("Was je ___ voor het eten.", ["handen"], "Lava as mãos.", ["v-hand"], choices=["handen","ogen","hoofd"], tr="Lava as mãos antes de comer."),
  ], diff=2, mins=5)

L(2, "Sintomas", "koorts, hoesten, verkouden, misselijk, duizelig.",
  ["Descrever sintomas comuns"],
  vocab=[V("v-koorts","koorts","febre","noun","de"), V("v-hoesten","hoesten","tossir","verb"), V("v-verkouden","verkouden","constipado","adjective"),
         V("v-griep","griep","gripe","noun","de"), V("v-misselijk","misselijk","enjoado|maldisposto","adjective"), V("v-duizelig","duizelig","tonto","adjective")],
  ex=[("Ik heb koorts.","Tenho febre."),("Ik ben verkouden.","Estou constipado."),("Ik hoest veel.","Tusso muito."),("Ik voel me misselijk.","Sinto-me enjoado.")],
  gram=[G("g-zich-voelen-intro","Sentir-se: zich voelen","**zich voelen** é reflexivo: *ik voel **me** ziek*, *hij voelt **zich** beter*. Pergunta: *Hoe voel je je?* (como te sentes?). Veremos os reflexivos em pormenor na Secção 4.",
    [("Ik voel me niet lekker.","Não me sinto bem.")],
    "«Niet lekker» com pessoas significa «indisposto», não «sem sabor».")],
  review=["v-ziek","v-moe","v-hoofd"],
  cefr=C, exs=[
    MA([("koorts","febre"),("hoesten","tossir"),("verkouden","constipado"),("griep","gripe"),("duizelig","tonto")], "Sintomas.", ["v-koorts","v-hoesten","v-verkouden","v-griep","v-duizelig"]),
    TR("pt-nl","Tenho febre.", ["Ik heb koorts"], "koorts hebben.", ["v-koorts"]),
    TR("pt-nl","Estou constipado.", ["Ik ben verkouden"], "verkouden zijn.", ["v-verkouden"]),
    TR("nl-pt","Ik voel me niet lekker.", ["Não me sinto bem","Sinto-me maldispost[o|a]"], "niet lekker = indisposto.", ["v-misselijk"]),
    FE(["Ik","ben","koorts."], 1, "heb", "koorts hebben: ik heb koorts.", ["v-koorts"]),
    MC("Tem a cabeça a andar à roda. Está…", ["*duizelig","verkouden|= constipado.","misselijk|= enjoado (estômago)."], "duizelig = tonto.", ["v-duizelig"]),
    CJ("hoesten","hij","Hij ___ de hele nacht.", ["hoest"], "hoesten → hij hoest (já acaba em t).", ["v-hoesten"]),
    LI("Ik denk dat ik griep heb.", ["Ik denk dat ik griep heb"], "Acho que tenho gripe.", "Verbo no fim depois de «dat».", ["v-griep"]),
    FB("Ik voel ___ niet goed.", ["me"], "zich voelen: ik voel me.", ["v-misselijk"], choices=["me","mij me","ik"], tr="Não me sinto bem."),
    DL([("Médico","Hoe voelt u zich?","Como se sente?"),("Paciente","")], ["*Niet goed. Ik heb hoofdpijn en koorts.","Ik ben koorts.|Usa-se «hebben».","Goedemorgen!|Não responde."], "Descrever sintomas.", ["v-koorts"]),
  ], diff=2, mins=6)

L(3, "Na médica de família", "Wat zijn de klachten? Sinds wanneer?",
  ["Explicar o problema na consulta e perceber perguntas do médico"],
  vocab=[V("v-klacht","klacht","queixa|sintoma","noun","de","klachten"), V("v-onderzoeken","onderzoeken","examinar","verb"),
         V("v-recept-med","recept","receita (médica)","noun","het",note="Mesma palavra que receita de cozinha."), V("v-rust","rust","descanso","noun","de"), V("v-beterschap","beterschap","as melhoras","interjection")],
  ex=[("Wat zijn de klachten?","Quais são as queixas?"),("Sinds wanneer heeft u dit?","Desde quando tem isto?"),("Ik schrijf een recept voor.","Vou passar uma receita."),("Beterschap!","As melhoras!")],
  gram=[G("g-huisarts-cultura","Ir à huisarts","A **huisarts** recomenda muitas vezes **rust** (descanso), **veel drinken** e **paracetamol**, e só receita antibióticos quando necessário. Isto é normal, não falta de cuidado. Para emergências: **112**; fora de horas: **huisartsenpost**.",
    [("Neem rust en drink veel water.","Descanse e beba muita água.")],
    "Em Portugal é comum esperar medicação; nos Países Baixos a abordagem é mais conservadora.")],
  review=["v-huisarts","v-sinds","v-koorts","v-hoofd"],
  cefr=C, exs=[
    MA([("klacht","queixa"),("onderzoeken","examinar"),("recept","receita"),("rust","descanso"),("beterschap","as melhoras")], "Consulta.", ["v-klacht","v-onderzoeken","v-recept-med","v-rust","v-beterschap"]),
    TR("nl-pt","Wat zijn de klachten?", ["Quais são as queixas","Quais são os sintomas"], "klachten.", ["v-klacht"]),
    TR("pt-nl","Tenho dores de cabeça desde segunda-feira.", ["Ik heb sinds maandag hoofdpijn","Sinds maandag heb ik hoofdpijn"], "sinds.", ["v-sinds"]),
    TR("nl-pt","Neem rust en drink veel water.", ["Descanse e beba muita água","Descansa e bebe muita água"], "rust nemen.", ["v-rust"]),
    MC("Ao despedir-se de alguém doente, diz-se…", ["*Beterschap!","Gefeliciteerd!|Isso é «parabéns».","Eet smakelijk!|Isso é «bom apetite»."], "Beterschap = as melhoras.", ["v-beterschap"]),
    AR("klacht","a queixa","de", "«De klacht».", ["v-klacht"]),
    FE(["Ik","ben","al","drie","dagen","hoofdpijn."], 1, "heb", "hoofdpijn hebben: ik heb al drie dagen hoofdpijn.", ["v-klacht"]),
    LI("Ik ga u even onderzoeken.", ["Ik ga u even onderzoeken"], "Vou examiná-lo um momento.", "even = um momento.", ["v-onderzoeken"]),
    CO("dialogue","Na consulta", "Huisarts: Goedemorgen. Wat zijn de klachten?\nPedro: Ik heb al drie dagen koorts en ik hoest veel.\nHuisarts: Heeft u ook keelpijn?\nPedro: Ja, een beetje.\nHuisarts: Ik denk dat het griep is. Neem rust, drink veel en neem paracetamol. Beterschap!",
       [("Há quanto tempo tem febre?", ["*Três dias","Uma semana","Desde ontem"]),("O que acha a médica que é?", ["*Gripe","Uma alergia","Nada de grave sem sintomas"]),("Receitou antibióticos?", ["*Não: descanso, líquidos e paracetamol","Sim","Não se diz"])],
       "Abordagem típica.", ["v-klacht","v-griep","v-rust"]),
    WO("Desde quando tem estas queixas?", ["Sinds","wanneer","heeft","u","deze","klachten?"], "Interrogativa + verbo + sujeito.", ["v-klacht"]),
  ], diff=3, mins=6)

L(4, "Emergências", "112, de ambulance, de spoedeisende hulp, help!",
  ["Pedir ajuda numa emergência"],
  vocab=[V("v-ambulance","ambulance","ambulância","noun","de"), V("v-spoed","spoedeisende hulp","urgências","noun","de",note="Abreviado: de SEH."),
         V("v-ongeluk","ongeluk","acidente","noun","het","ongelukken"), V("v-bellen-112","112 bellen","ligar para o 112","expression"), V("v-gewond","gewond","ferido","adjective")],
  ex=[("Bel 112!","Liga para o 112!"),("Er is een ongeluk gebeurd.","Houve um acidente."),("Iemand is gewond.","Alguém está ferido."),("Help!","Socorro!")],
  review=["v-helpen","v-ziekenhuis","v-snel"],
  cefr=C, exs=[
    MA([("ambulance","ambulância"),("spoedeisende hulp","urgências"),("ongeluk","acidente"),("gewond","ferido")], "Emergências.", ["v-ambulance","v-spoed","v-ongeluk","v-gewond"]),
    TR("pt-nl","Liga para o 112!", ["Bel 112","Bel honderdtwaalf","Bel één één twee"], "Imperativo.", ["v-bellen-112"]),
    TR("nl-pt","Er is een ongeluk gebeurd.", ["Houve um acidente","Aconteceu um acidente"], "gebeuren = acontecer.", ["v-ongeluk"]),
    TR("pt-nl","Alguém está ferido.", ["Iemand is gewond"], "gewond.", ["v-gewond","v-iemand"]),
    AR("ongeluk","o acidente","het", "«Het ongeluk».", ["v-ongeluk"]),
    MC("Qual é o número de emergência nos Países Baixos?", ["*112","911|É o dos EUA.","115|Não."], "112 é europeu.", ["v-bellen-112"]),
    LI("We hebben een ambulance nodig!", ["We hebben een ambulance nodig"], "Precisamos de uma ambulância!", "nodig hebben = precisar.", ["v-ambulance"]),
    FE(["Er","is","een","ongeluk","gebeuren."], 4, "gebeurd", "Particípio: er is een ongeluk gebeurd.", ["v-ongeluk"]),
    DL([("112","Alarmnummer 112, welke dienst wilt u?","112, que serviço deseja?"),("Você","")], ["*Ambulance! Er is een ongeluk gebeurd.","Goedemiddag, een kop koffie.|Não é o momento.","Ik heb een afspraak.|Não é uma emergência."], "Indicar o serviço e o problema.", ["v-ambulance","v-ongeluk"]),
    WO("Onde ficam as urgências?", ["Waar","is","de","spoedeisende","hulp?"], "Pergunta.", ["v-spoed"]),
  ], diff=2, mins=5)

L(5, "Estar doente no trabalho", "Revisão: ziekmelden, sintomas, consulta.",
  ["Avisar que está doente e descrever o estado"],
  vocab=[V("v-ziekmelden","zich ziekmelden","dar baixa|avisar que está doente","verb",note="Ik meld me ziek.")],
  ex=[("Ik meld me ziek.","Aviso que estou doente (não vou trabalhar)."),("Ik ben morgen waarschijnlijk weer beter.","Amanhã provavelmente já estou melhor.")],
  review=["v-koorts","v-griep","v-klacht","v-huisarts","v-beterschap","v-rust","v-hoofd"],
  cefr=C, exs=[
    TR("pt-nl","Aviso que estou doente.", ["Ik meld me ziek","Ik meld mij ziek"], "zich ziekmelden.", ["v-ziekmelden"]),
    TR("nl-pt","Ik blijf vandaag thuis, want ik heb koorts.", ["Hoje fico em casa, porque tenho febre"], "want + ordem normal.", ["v-koorts"]),
    MC("Telefona ao chefe às 8h porque tem gripe. O que diz?", ["*Ik meld me ziek, ik heb griep.","Ik ben griep, doei.|Usa-se «hebben» e é brusco.","Beterschap!|Isso diz-se ao doente."], "Avisar ao chefe.", ["v-ziekmelden"]),
    FE(["Ik","heb","griep,","dus","ik","meld","ziek."], 5, "meld me", "Reflexivo: ik meld me ziek.", ["v-ziekmelden"]),
    LI("Ik heb sinds gisteren koorts.", ["Ik heb sinds gisteren koorts"], "Tenho febre desde ontem.", "sinds gisteren.", ["v-koorts"]),
    MA([("hoofdpijn","dor de cabeça"),("keelpijn","dor de garganta"),("buikpijn","dor de barriga"),("rugpijn","dor de costas")], "Dores.", ["v-hoofd","v-keel","v-buik","v-rug"]),
    CO("text","Mensagem ao chefe", "Beste Marieke,\nIk voel me helaas niet goed. Ik heb hoge koorts en hoofdpijn. Ik meld me vandaag ziek en ik ga naar de huisarts. Ik laat je morgen weten hoe het gaat.\nGroeten, Ana",
       [("Que sintomas tem a Ana?", ["*Febre alta e dores de cabeça","Tosse e dores de garganta","Dores de barriga"]),("O que vai fazer?", ["*Ir à médica de família","Trabalhar a partir de casa","Ir às urgências"])],
       "laten weten = avisar/dar notícias.", ["v-ziekmelden","v-koorts"]),
    DL([("Colega","Je ziet er moe uit. Gaat het?","Pareces cansada. Estás bem?"),("Ana","")], ["*Niet echt, ik denk dat ik verkouden word.","Ja, beterschap!|Isso diz-se a quem está doente.","Ik ben moe uit.|Não faz sentido."], "Explicar como se sente.", ["v-verkouden"]),
    WO("As melhoras para a tua mãe!", ["Beterschap","voor","je","moeder!"], "beterschap voor.", ["v-beterschap"]),
    SW("Escreva uma mensagem ao seu chefe a dizer que está doente (sintomas e o que vai fazer).", ["Beste [Tom|Marieke](,) ik voel me niet goed(.) Ik heb koorts(.) Ik meld me vandaag ziek(.) Groeten"],
       ["Abertura com «Beste»","Pelo menos um sintoma","«ik meld me ziek»","Fecho («Groeten»)"], 10, "Compare com a mensagem da Ana.", ["v-ziekmelden"]),
  ], diff=3, mins=7)

W()
